import * as wt from 'node:worker_threads';

async function main(): Promise<void> {
  process.on('workerMessage', (v: any, source: number): void => { console.log('main got', v.kind, source); });
  const worker = new wt.Worker(`
    const wt = require('node:worker_threads');
    const keep = setInterval(() => {}, 1000);
    wt.parentPort.on('message', (m) => {
      if (m === 'send') {
        const c = new ArrayBuffer(5);
        wt.postMessageToThread(0, { kind: 'bytes', c }, [c]).then(() => wt.parentPort.postMessage({ tag: 'sent', len: c.byteLength, det: c.detached }));
      } else {
        const kept = new ArrayBuffer(4);
        wt.postMessageToThread(99, 1, [kept]).then(() => wt.parentPort.postMessage({ tag: 'unknown resolved' }), (e) => wt.parentPort.postMessage({ tag: 'unknown', name: e.name, code: e.code, message: e.message, len: kept.byteLength, det: kept.detached }));
      }
    });
    wt.parentPort.postMessage({ tag: 'ready' });
  `, { eval: true });
  const queue: any[] = [];
  worker.on('message', (m: any): void => { queue.push(m); });
  const next = async (): Promise<any> => {
    while (queue.length === 0) { await new Promise<void>((resolve: () => void): void => { setTimeout(resolve, 1); }); }
    return queue.shift();
  };
  await next();
  worker.postMessage('send');
  console.log('worker sent', JSON.stringify(await next()));
  worker.postMessage('unknown');
  const u: any = await next();
  console.log('unknown', u.name, u.code, JSON.stringify(u.message), u.len, u.det);
  await worker.terminate();
  const late = new ArrayBuffer(4);
  worker.postMessage(1, [late]);
  console.log('after exit', late.byteLength, late.detached);
  console.log('done');
}
